<template><el-tag :type="type" effect="light" round>{{labels[value]||value||'未知'}}</el-tag></template>
<script setup>import{computed}from'vue';const p=defineProps({value:String});const labels={WAITING:'等待中',PARSING:'解析中',CLEANING:'清洗中',CHUNKING:'分块中',VECTORIZING:'向量化',SUCCESS:'成功',FAILED:'失败',DISABLED:'已停用',INTERRUPTED:'已中断',RUNNING:'进行中',CANCELLED:'已取消',AWAITING_REVIEW:'等待教师确认',PENDING:'待审核',APPROVED:'已通过',NEEDS_REVISION:'需修改',REJECTED:'未通过',ARCHIVED:'已归档',ACTIVE:'使用中',DRAFT:'草稿',EDITING:'编辑中',COMPLETED:'已完成',EXPORTED:'已导出'};const type=computed(()=>['SUCCESS','APPROVED','ACTIVE','COMPLETED'].includes(p.value)?'success':['FAILED','REJECTED'].includes(p.value)?'danger':['WAITING','PENDING','AWAITING_REVIEW','NEEDS_REVISION','INTERRUPTED'].includes(p.value)?'warning':p.value==='DISABLED'||p.value==='ARCHIVED'?'info':'primary')</script>
